svg.script:
(function () {
  var NS = 'http://www.w3.org/2000/svg', U = 19.1, Y0 = 750.5, RATE = 0.068 / 50, T = 12;
  // the swipes: hold at $50, swipe up to $63.40, hold, swipe down to $38.80, hold, back to $50 (seconds, value)
  var K = [[0, 50], [0.9, 50], [2.5, 63.4], [4.3, 63.4], [6.3, 38.8], [8.2, 38.8], [10.1, 50], [12, 50]];
  var ease = function (p) { return p < .5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2; };
  function value(t) {
    t = ((t % T) + T) % T;
    for (var i = 0; i < K.length - 1; i++) if (t <= K[i + 1][0]) {
      var a = K[i], b = K[i + 1], p = (t - a[0]) / (b[0] - a[0]); return a[1] + (b[1] - a[1]) * ease(p);
    }
    return 50;
  }
  var ticks = document.getElementById('ruler-ticks'), amt = document.getElementById('amt'),
      ztc = document.getElementById('ztc'), sell = document.getElementById('selltx');
  function el(tag, at, text) { var e = document.createElementNS(NS, tag); for (var k in at) e.setAttribute(k, at[k]); if (text) e.textContent = text; return e; }
  function render(t) {
    var v = value(t), shown = Math.round(v * 10) / 10;
    while (ticks.firstChild) ticks.removeChild(ticks.firstChild);
    for (var u = Math.floor(v) - 30; u <= Math.ceil(v) + 30; u++) {
      if (u % 2) continue;
      var y = Y0 - (u - v) * U;
      if (y < 190 || y > 1420) continue;
      if (u % 10 === 0) {
        ticks.appendChild(el('rect', {x: 799, y: (y - 3).toFixed(1), width: 78, height: 6, fill: '#b2b2b2'}));
        ticks.appendChild(el('text', {x: u >= 50 && u < 60 ? 799.5 : 803.5, y: (y + 42).toFixed(1), 'font-size': 23.5, fill: '#b0b0b0'}, String(u)));
      } else {
        ticks.appendChild(el('rect', {x: 857, y: (y - 1.5).toFixed(1), width: 20, height: 3, fill: '#d6d6d6'}));
      }
    }
    amt.textContent = shown.toFixed(2);
    ztc.textContent = (shown * RATE).toFixed(3);
    sell.textContent = 'Sell $' + shown.toFixed(2) + ' worth Zitcoin';
  }
  window.__seek = function (t) { window.__manual = true; render(t); };
  render(0);
  var t0 = null;
  (function loop(now) { if (window.__manual) return; if (t0 === null) t0 = now; render((now - t0) / 1000); requestAnimationFrame(loop); })(performance.now());
})();
